#[test]
fn test_the_checker_notices_every_way_of_being_broken() {
    let grl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let gfl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ggp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let grg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let refs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    gt_page(grl, gfl, ggp, grg, refs, 1);
    crate::port::cells_push(grl, 0);
    crate::testport::assert_eq(gl_check(grl, gfl, ggp, grg, refs), 1, "a stride");
    crate::port::cells_drop(grl, 48);
    grl_set(grl, 1, 19, 5);
    crate::testport::assert_eq(gl_check(grl, gfl, ggp, grg, refs), 2, "a rule's group outside ggp");
    grl_set(grl, 1, 19, 0);
    gfl_set(gfl, 0, 12, 3);
    crate::testport::assert_eq(gl_check(grl, gfl, ggp, grg, refs), 2, "a fill's group outside ggp");
    gfl_set(gfl, 0, 12, 0);
    ggp_set(ggp, 0, 3, 9);
    crate::testport::assert_eq(gl_check(grl, gfl, ggp, grg, refs), 3, "a member run outside refs");
    ggp_set(ggp, 0, 3, 2);
    grl_set(grl, 0, 10, 4);
    crate::testport::assert_eq(gl_check(grl, gfl, ggp, grg, refs), 4, "an orientation outside go");
    grl_set(grl, 0, 10, 1);
    grl_set(grl, 0, 9, -1);
    crate::testport::assert_eq(gl_check(grl, gfl, ggp, grg, refs), 4, "a negative thickness");
    grl_set(grl, 0, 9, 100);
    grl_set(grl, 0, 1, 99999);
    crate::testport::assert_eq(gl_check(grl, gfl, ggp, grg, refs), 4, "a box upside down");
    grl_set(grl, 0, 1, 1000);
    grg_set(grg, 0, 5, 9);
    crate::testport::assert_eq(gl_check(grl, gfl, ggp, grg, refs), 5, "a region of an unknown kind");
    grg_set(grg, 0, 5, 1);
    grg_set(grg, 0, 8, -1);
    crate::testport::assert_eq(gl_check(grl, gfl, ggp, grg, refs), 5, "a half subject");
    grg_set(grg, 0, 8, 4);
    rf_add(refs, 41, 9);
    crate::testport::assert_eq(gl_check(grl, gfl, ggp, grg, refs), 6, "a reference into a rule that is not there");
    crate::port::cells_drop(refs, 4);
    crate::testport::assert_eq(gl_check(grl, gfl, ggp, grg, refs), 0, "sound again");
}
