    let pgrl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pgfl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pggp: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pgrg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let prefs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    gt_page(pgrl, pgfl, pggp, pgrg, prefs, 1);
    gl_append(grl, gfl, ggp, grg, pgrl, pgfl, pggp, pgrg, 0);
    rf_add(refs, ea_paths(), 7);
    rf_add(refs, ea_pts(), 3);
    gt_page(pgrl, pgfl, pggp, pgrg, prefs, 2);
    gl_append(grl, gfl, ggp, grg, pgrl, pgfl, pggp, pgrg, 2);
    rf_add(refs, ea_paths(), 7);
    rf_add(refs, ea_pts(), 3);
