    crate::testport::assert_eq(ggp_count(ggp), 2, "groups");
    crate::testport::assert_eq(grg_count(grg), 2, "regions");
    crate::testport::assert_eq(grl_get(grl, 2, 19), 1, "the second page's rule is in the document's second group");
    crate::testport::assert_eq(gfl_get(gfl, 1, 12), 1, "and its fill");
    crate::testport::assert_eq(grl_get(grl, 0, 19), 0, "the first page's is not moved");
    crate::testport::assert_eq(ggp_get(ggp, 1, 2), 2, "the second group's member run starts after the first page's refs");
    crate::testport::assert_eq(ggp_get(ggp, 1, 4), -1, "an absent run stays absent");
    crate::testport::assert_eq(grg_get(grg, 1, 7), 13, "a region's subject, an evidence row, is not re-based");
