pub(crate) fn gt_width(kind: i32, arg: i32) -> i32 {
    // How many cells a field of the dump table covers.
    if kind == 3 {
        return 4;
    }
    if (kind == 4) || (kind == 5) {
        return 2;
    }
    return 1;
}
#[test]
fn test_every_cell_is_printed_or_named_spare() {
    // per arena of the field table: the cells its rows cover, plus its spare cells, are its stride, and no two rows overlap
    let mut a: i32 = 0;
    let mut k: i32 = 0;
    let mut covered: i32 = 0;
    let mut next: i32 = 0;
    let mut f: i32 = 0;
    while a < 4 {
        covered = 0;
        next = 0;
        k = 0;
        while k < GL_FX[(a * 4 + 1) as usize] {
            f = GL_FD[((GL_FX[(a * 4 + 0) as usize] + k) * 6 + 1) as usize];
            crate::testport::assert_that(f >= next, "the fields are in stride order and do not overlap");
            covered += gt_width(GL_FD[((GL_FX[(a * 4 + 0) as usize] + k) * 6 + 2) as usize], GL_FD[((GL_FX[(a * 4 + 0) as usize] + k) * 6 + 5) as usize]);
            next = f + gt_width(GL_FD[((GL_FX[(a * 4 + 0) as usize] + k) * 6 + 2) as usize], GL_FD[((GL_FX[(a * 4 + 0) as usize] + k) * 6 + 5) as usize]);
            k += 1;
        }
        crate::testport::assert_eq(covered + GL_FX[(a * 4 + 3) as usize], GL_FX[(a * 4 + 2) as usize], "printed plus spare is the stride");
        a += 1;
    }
    crate::testport::assert_eq(a, 4, "four arenas");
}
